//! Shortening ("mangling") of the export names a module exposes to other modules.
//!
//! A module's export keys usually only exist to link modules together: the producing module emits
//! `{ someVeryLongExportName: () => … }` and every consumer reads
//! `ns["someVeryLongExportName"]`. Both sides are generated by us, so the key can be replaced by a
//! much shorter one — as long as producer and consumer agree, and as long as the name is not
//! observable from user code.
//!
//! [`mangled_export_names`] is the single source of truth for that mapping. Both the producer
//! ([`super::export::EsmExports::code_generation`]) and the consumer
//! ([`super::base::ReferencedAsset`]) ask it for the *target* module's map, so they cannot
//! disagree. It returns `None` whenever the module has to keep its original names.

use anyhow::Result;
use turbo_frozenmap::FrozenMap;
use turbo_rcstr::RcStr;
use turbo_tasks::{ResolvedVc, Vc};
use turbo_tasks_hash::shorten_to_unique_names;
use turbopack_core::{
    chunk::{ChunkingContext, MinifyType},
    module_graph::binding_usage_info::ModuleExportUsageInfo,
};

use crate::chunk::{EcmascriptChunkPlaceable, EcmascriptExports};

/// The export name of the default export. Not mangled: the CommonJS interop layer and the
/// `__esModule` handling in the runtime look it up by name, an embedder's runtime may read
/// `.default` off a loaded module by string, and it is only seven characters to begin with.
const DEFAULT_EXPORT: &str = "default";
/// Never mangled — it is part of the interop contract with CommonJS consumers.
const ES_MODULE_FLAG: &str = "__esModule";

/// A module's export name mapping: original export name -> the key actually used in the output.
///
/// It covers every export the module emits that is eligible for mangling (so not `default` or
/// `__esModule`), including the ones whose key is unchanged because the original name was already
/// short enough to keep — which makes the map a complete description of the module's emitted keys.
/// A name absent from the map keeps its original name.
#[turbo_tasks::value(transparent)]
pub struct MangledExportNames(pub FrozenMap<RcStr, RcStr>);

#[turbo_tasks::value(transparent)]
pub struct OptionMangledExportNames(pub Option<ResolvedVc<MangledExportNames>>);

/// Computes the mangled export names of `module`, or `None` if the module's exports must keep
/// their original names.
///
/// Both the producing and the consuming side call this for the same `module`, which is what
/// guarantees they agree. The mapping covers the module's *used* exports: unused exports are not
/// emitted at all, so giving them names would only make the remaining names longer.
///
/// A module keeps its original names when any of these hold:
///
/// 1. mangling is disabled for the module, or names are not being mangled at all — either we're not
///    minifying, or minification was asked to keep names (`MinifyType::Minify` with no
///    `MangleType`), in which case mangled export keys would only make the output harder to read,
/// 2. its export usage is [`ModuleExportUsageInfo::All`] — a namespace import that could not be
///    lowered to named imports, a computed property access, an unresolvable `export *`, or a module
///    referenced from outside the module graph (entries, which are seeded with `All`),
/// 3. it is read through a namespace value somewhere — a namespace binding's member reads or
///    destructuring, or the object a dynamic `import()` resolves to (`import(/* webpackExports:
///    [...] */ "…")`). We know which names are used, but not that every read of them was lowered to
///    a direct named access, so an original name may still be read by user code,
/// 4. its exports are not statically known ECMAScript exports, or contain dynamic re-exports.
#[turbo_tasks::function]
pub async fn mangled_export_names(
    module: ResolvedVc<Box<dyn EcmascriptChunkPlaceable>>,
    chunking_context: Vc<Box<dyn ChunkingContext>>,
) -> Result<Vc<OptionMangledExportNames>> {
    // (1) Disabled for this module, or names aren't being mangled in this build at all.
    if !*module.mangle_export_names().await?
        || !matches!(
            *chunking_context.minify_type().await?,
            MinifyType::Minify {
                mangle: Some(_),
                ..
            }
        )
    {
        return Ok(Vc::cell(None));
    }

    // (4) Only statically known ESM exports can be renamed.
    let EcmascriptExports::EsmExports(exports) = *module.get_exports().await? else {
        return Ok(Vc::cell(None));
    };

    let usage = chunking_context
        .module_export_usage(*ResolvedVc::upcast(module))
        .await?;

    // (3) An original name may still be read through a namespace value.
    if usage.namespace_object_may_escape {
        return Ok(Vc::cell(None));
    }

    // (2) We don't know which exports are used, so we don't know that all uses are ours.
    let usage_info = usage.export_usage.await?;
    let ModuleExportUsageInfo::Exports(used) = &*usage_info else {
        return Ok(Vc::cell(None));
    };
    if used.is_empty() {
        return Ok(Vc::cell(None));
    }

    let expanded = exports.expand_exports(*usage.export_usage).await?;

    // (4) `export * from "./some-dynamic-cjs"` is resolved at runtime by property access on the
    // original names.
    if !expanded.dynamic_exports.is_empty() {
        return Ok(Vc::cell(None));
    }

    // Mangle exactly the exports that are emitted, minus the ones whose names are part of a
    // runtime contract.
    let names = expanded
        .exports
        .iter()
        .map(|(name, _)| name)
        .filter(|name| name.as_str() != DEFAULT_EXPORT && name.as_str() != ES_MODULE_FLAG)
        .collect::<Vec<_>>();

    if names.is_empty() {
        return Ok(Vc::cell(None));
    }

    let mangled = shorten_to_unique_names(names.iter().map(|name| name.as_str()));

    let map = names
        .iter()
        .map(|name| {
            let mangled = mangled
                .get(name.as_str())
                .expect("every name passed in has a mangled name");
            ((*name).clone(), RcStr::from(mangled.as_str()))
        })
        .collect::<Vec<(RcStr, RcStr)>>();

    Ok(Vc::cell(Some(
        MangledExportNames(FrozenMap::from(map)).resolved_cell(),
    )))
}

/// Looks up the key that `export` is emitted under in `module`, which is `export` itself unless
/// the module's exports are mangled.
pub async fn mangled_export_name(
    module: ResolvedVc<Box<dyn EcmascriptChunkPlaceable>>,
    chunking_context: Vc<Box<dyn ChunkingContext>>,
    export: &RcStr,
) -> Result<RcStr> {
    let Some(names) = *mangled_export_names(*module, chunking_context).await? else {
        return Ok(export.clone());
    };
    let names = names.await?;
    Ok(names.get(export).cloned().unwrap_or_else(|| export.clone()))
}
